CREATE TABLE [dbo].[RepOutKPI](	  [date] DATETIME NOT NULL	, [campaignId] SMALLINT NOT NULL	, [campaign] VARCHAR(255) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [totalCalls] SMALLINT NOT NULL	, [avgXfer] SMALLINT NOT NULL	, [avgCallTime] SMALLINT NOT NULL	, [c10Secs] SMALLINT NOT NULL	, [c20Secs] SMALLINT NOT NULL	, [c30Secs] SMALLINT NOT NULL	, [cMaxSecs] SMALLINT NOT NULL	, [AnsweredCalls] SMALLINT NOT NULL	, [answeredCallsPctg] SMALLINT NOT NULL	, [remainingCalls] SMALLINT NOT NULL	, [remainingCallsPctg] SMALLINT NOT NULL	, [abandonedCalls] SMALLINT NOT NULL	, [abandonedCallsPctg] SMALLINT NOT NULL	, [avgTimeBetweenCalls] SMALLINT NOT NULL	, [year] INT NULL	, [month] INT NULL	, [day] INT NULL	, [hour] INT NULL	, [minutes] INT NULL)CREATE NONCLUSTERED INDEX [IX_RepOutKPI] ON [dbo].[RepOutKPI] ([date] ASC)